7	export const OPENROUTER_API_URL = "https://openrouter.ai/api/v1/chat/completions";
8	export const DEFAULT_ANTHROPIC_MODEL = "claude-sonnet-4-6";
9	
10	// Construct a fresh Anthropic client per call. The SDK is cheap to instantiate
11	// and per-call construction means an env-var rotation (e.g. swapping
12	// ANTHROPIC_API_KEY in the Vercel dashboard) takes effect on the next request
13	// without needing a redeploy or process restart.
14	export function makeAnthropicClient(apiKey: string): Anthropic {
15	  return new Anthropic({ apiKey });
16	}
17	
18	export class OpenRouterError extends Error {
19	  status: number;
20	  details: string;
21	  constructor(status: number, details: string) {
22	    super(`OpenRouter API error: ${status}`);
23	    this.name = "OpenRouterError";
24	    this.status = status;
25	    this.details = details;
26	  }
27	}
28	
29	export type LlmCallUsage = {
30	  provider: "anthropic" | "openrouter" | "mock" | "cache";
31	  model: string;
32	  inputTokens: number;
33	  outputTokens: number;
34	  costUsd: number;
35	  latencyMs: number;
36	};
37	
38	/** OpenRouter-compatible response_format for structured outputs.
39	 *  See https://openrouter.ai/docs/guides/features/structured-outputs */
40	export type ResponseFormat = {
41	  type: "json_schema";
42	  json_schema: {
43	    name: string;
44	    strict: boolean;
45	    schema: Record<string, unknown>;
46	  };
47	};
48	
49	type CallLlmOptions = {
50	  endpoint: string;
51	  systemPrompt: string;
52	  userContent: string;
53	  maxTokens: number;
54	  anthropicModel?: string;
55	  openRouterModel?: string;
56	  /** When provided, enforces structured JSON output via OpenRouter's response_format.
57	   *  Only used with the OpenRouter provider (Anthropic direct API does not support this). */
58	  responseFormat?: ResponseFormat;
59	};
60	
61	export type CacheKey = {
62	  model: string;
63	  systemPrompt: string;
64	  userContent: string;
65	  maxTokens: number;
66	};
67	
68	type CallLlmResult = {
69	  text: string;
70	  usage: LlmCallUsage;
71	  cacheKey?: CacheKey;
72	};
73	
74	/** Record analytics and write to cache. Failures are silently ignored
75	 *  so they never break the LLM call that produced the result. */
76	async function recordAndCache(
77	  endpoint: string,
78	  usage: LlmCallUsage,
79	  text: string,
80	  cacheHash: string,
81	  cacheKey: CacheKey,
82	): Promise<CallLlmResult> {
83	  try {
84	    appendAnalyticsEntry({
85	      id: randomUUID(),
86	      endpoint,
87	      ...usage,
88	      timestamp: new Date().toISOString(),
89	    });
90	  } catch { /* persistence failure must not break LLM calls */ }
91	  const result: CallLlmResult = { text, usage, cacheKey };
92	  if (text) {
93	    try { await setCachedResult(cacheHash, result); } catch { /* cache write failure is non-fatal */ }
94	  }
95	  return result;
96	}
97	
98	/** Centralized LLM call with Anthropic -> OpenRouter -> mock fallback.
99	 *  Returns the raw text response and usage/cost metadata.
100	 *  On mock fallback, returns text: "" — the caller provides its own mock text. */
101	export async function callLlm({
102	  endpoint,
103	  systemPrompt,
104	  userContent,
105	  maxTokens,
106	  anthropicModel,
107	  openRouterModel,
108	  responseFormat,
109	}: CallLlmOptions): Promise<CallLlmResult> {
110	  // Resolve effective model for cache key
111	  const anthropicKey = process.env.ANTHROPIC_API_KEY;
112	  const openRouterKey = process.env.OPENROUTER_API_KEY;
113	  const effectiveModel = anthropicKey
114	    ? (anthropicModel ?? DEFAULT_ANTHROPIC_MODEL)
115	    : (openRouterKey && openRouterModel)
116	      ? openRouterModel
117	      : "mock";
118	
119	  // Compute hash once, reuse for cache get and set
120	  const cacheHash = computeHash(effectiveModel, systemPrompt, userContent, maxTokens);
121	  const cacheKey: CacheKey = { model: effectiveModel, systemPrompt, userContent, maxTokens };
122	
123	  // Check cache before making any LLM call
124	  const cached = await getCachedResult(effectiveModel, systemPrompt, userContent, maxTokens);
125	  if (cached) {
126	    console.log(`[${endpoint}] cache hit (model: ${effectiveModel}, hash: ${cacheHash.slice(0, 8)})`);
127	    return { text: cached.text, usage: cached.usage };
128	  }
129	
130	  if (anthropicKey) {
131	    const model = anthropicModel ?? DEFAULT_ANTHROPIC_MODEL;
132	    const start = Date.now();
133	    const client = makeAnthropicClient(anthropicKey);
134	    const message = await client.messages.create({
135	      model,
136	      max_tokens: maxTokens,
137	      system: systemPrompt,
138	      messages: [{ role: "user", content: userContent }],
139	      ...(responseFormat && {
140	        output_config: {
141	          format: {
142	            type: "json_schema" as const,
143	            schema: responseFormat.json_schema.schema,
144	          },
145	        },
146	      }),
147	    });
148	    const latencyMs = Date.now() - start;
149	    const text = message.content[0].type === "text" ? message.content[0].text : "";
150	    const usage: LlmCallUsage = {
151	      provider: "anthropic",
152	      model,
153	      inputTokens: message.usage.input_tokens,
154	      outputTokens: message.usage.output_tokens,
155	      costUsd: computeCost(model, message.usage.input_tokens, message.usage.output_tokens),
156	      latencyMs,
157	    };
158	    return recordAndCache(endpoint, usage, text, cacheHash, cacheKey);
159	  }
160	
161	  if (openRouterKey && openRouterModel) {
162	    const start = Date.now();
163	    const response = await fetch(OPENROUTER_API_URL, {
164	      method: "POST",
165	      headers: {
166	        "Content-Type": "application/json",
167	        Authorization: `Bearer ${openRouterKey}`,
168	      },
169	      body: JSON.stringify({
170	        model: openRouterModel,
171	        messages: [
172	          { role: "system", content: systemPrompt },
173	          { role: "user", content: userContent },
174	        ],
175	        ...(responseFormat && { response_format: responseFormat }),
176	      }),
177	    });
178	    const latencyMs = Date.now() - start;
179	
180	    if (!response.ok) {
181	      const errorBody = await response.text();
182	      // Log only status + endpoint here; the body can echo parts of the request
183	      // and we don't want it on disk in plaintext. The body still rides on
184	      // OpenRouterError so route handlers can decide what (if anything) to
185	      // surface to the caller.
186	      console.error(`[${endpoint}] OpenRouter error: status=${response.status}`);
187	      throw new OpenRouterError(response.status, errorBody);
188	    }
189	
190	    const data = await response.json();
191	    const text = data.choices?.[0]?.message?.content ?? "";
192	    const inputTokens = data.usage?.prompt_tokens ?? 0;
193	    const outputTokens = data.usage?.completion_tokens ?? 0;
194	    const usage: LlmCallUsage = {
195	      provider: "openrouter",
196	      model: openRouterModel,
197	      inputTokens,
198	      outputTokens,
199	      costUsd: computeCost(openRouterModel, inputTokens, outputTokens),
200	      latencyMs,
201	    };
202	    return recordAndCache(endpoint, usage, text, cacheHash, cacheKey);
203	  }
204	
205	  // Mock fallback — caller provides its own mock text
206	  console.warn(`[${endpoint}] No API key configured — returning mock response.\n\n To generate real responses, add ANTHROPIC_API_KEY or OPENROUTER_API_KEY to .env.local`);
207	  const usage: LlmCallUsage = {
208	    provider: "mock",
209	    model: "mock",
210	    inputTokens: 0,
211	    outputTokens: 0,
212	    costUsd: 0,
213	    latencyMs: 0,
214	  };
215	  try {
216	    appendAnalyticsEntry({
217	      id: randomUUID(),
218	      endpoint,
219	      ...usage,
220	      timestamp: new Date().toISOString(),
221	    });
222	  } catch { /* persistence failure must not break LLM calls */ }
223	  return { text: "", usage };
224	}
225

1	import { randomUUID } from "crypto";
2	import { computeCost } from "./costs";
3	import { appendAnalyticsEntry } from "@/app/lib/analytics/persist";
4	import { computeHash, getCachedResult, setCachedResult } from "./cache";
5	import {
6	  OPENROUTER_API_URL,
7	  DEFAULT_ANTHROPIC_MODEL,
8	  makeAnthropicClient,
9	} from "./callLlm";
10	import type { LlmCallUsage } from "./callLlm";
11	
12	export const SSE_HEADERS = {
13	  "Content-Type": "text/event-stream",
14	  "Cache-Control": "no-cache",
15	  Connection: "keep-alive",
16	} as const;
17	
18	const encoder = new TextEncoder();
19	
20	/** Format a single SSE event as a Uint8Array. */
21	export function sseEvent(event: string, data: unknown): Uint8Array {
22	  return encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
23	}
24	
25	/** Create an Error with a `details` property for structured error info.
26	 *  The streaming catch block intentionally does not log or forward `details`
27	 *  over SSE (provider error bodies can echo request content), but the property
28	 *  remains attached to the thrown Error for any in-process consumer that
29	 *  opts in to reading it. */
30	function errorWithDetails(message: string, details: string): Error {
31	  const err = new Error(message);
32	  (err as Error & { details: string }).details = details;
33	  return err;
34	}
35	
36	type StreamLlmOptions = {
37	  endpoint: string;
38	  systemPrompt: string;
39	  userContent: string;
40	  maxTokens: number;
41	  anthropicModel?: string;
42	  openRouterModel?: string;
43	};
44	
45	/** Record analytics and write to cache (same as callLlm's recordAndCache). */
46	async function recordAndCache(
47	  endpoint: string,
48	  usage: LlmCallUsage,
49	  text: string,
50	  cacheHash: string,
51	): Promise<void> {
52	  try {
53	    appendAnalyticsEntry({
54	      id: randomUUID(),
55	      endpoint,
56	      ...usage,
57	      timestamp: new Date().toISOString(),
58	    });
59	  } catch { /* persistence failure must not break LLM calls */ }
60	  if (text) {
61	    try { await setCachedResult(cacheHash, { text, usage }); } catch { /* non-fatal */ }
62	  }
63	}
64	
65	/**
66	 * Streaming LLM call returning a ReadableStream of SSE events.
67	 *
68	 * SSE protocol:
69	 *   event: token   — { text: "partial chunk" }
70	 *   event: done    — { text: "full accumulated text", usage: LlmCallUsage }
71	 *   event: error   — { error: "message", details: "..." }
72	 *
73	 * Provider chain mirrors callLlm(): Anthropic → OpenRouter → mock.
74	 * Cache hits emit a single `done` event.
75	 */
76	export function streamLlm({
77	  endpoint,
78	  systemPrompt,
79	  userContent,
80	  maxTokens,
81	  anthropicModel,
82	  openRouterModel,
83	}: StreamLlmOptions): ReadableStream<Uint8Array> {
84	  const anthropicKey = process.env.ANTHROPIC_API_KEY;
85	  const openRouterKey = process.env.OPENROUTER_API_KEY;
86	  const effectiveModel = anthropicKey
87	    ? (anthropicModel ?? DEFAULT_ANTHROPIC_MODEL)
88	    : (openRouterKey && openRouterModel)
89	      ? openRouterModel
90	      : "mock";
91	
92	  const cacheHash = computeHash(effectiveModel, systemPrompt, userContent, maxTokens);
93	
94	  return new ReadableStream<Uint8Array>({
95	    async start(controller) {
96	      try {
97	        // Check cache
98	        const cached = await getCachedResult(effectiveModel, systemPrompt, userContent, maxTokens);
99	        if (cached) {
100	          console.log(`[${endpoint}] stream cache hit (model: ${effectiveModel}, hash: ${cacheHash.slice(0, 8)})`);
101	
102	          if (process.env.SIMULATE_STREAM_FROM_CACHE === "true") {
103	            // Simulate token-by-token streaming from cache for testing
104	            // partial-JSON rendering without making expensive API calls.
105	            console.log(`[${endpoint}] simulating stream from cache (${cached.text.length} chars)`);
106	            await simulateStreamFromCache(controller, cached.text, cached.usage);
107	          } else {
108	            controller.enqueue(sseEvent("done", { text: cached.text, usage: cached.usage }));
109	          }
110	          controller.close();
111	          return;
112	        }
113	
114	        if (anthropicKey) {
115	          await streamAnthropic(controller, {
116	            apiKey: anthropicKey,
117	            model: anthropicModel ?? DEFAULT_ANTHROPIC_MODEL,
118	            systemPrompt,
119	            userContent,
120	            maxTokens,
121	            endpoint,
122	            cacheHash,
123	          });
124	        } else if (openRouterKey && openRouterModel) {
125	          await streamOpenRouter(controller, {
126	            apiKey: openRouterKey,
127	            model: openRouterModel,
128	            systemPrompt,
129	            userContent,
130	            maxTokens,
131	            endpoint,
132	            cacheHash,
133	          });
134	        } else {
135	          // Mock fallback
136	          console.warn(`[${endpoint}] No API key configured — returning mock stream.`);
137	          const usage: LlmCallUsage = {
138	            provider: "mock",
139	            model: "mock",
140	            inputTokens: 0,
141	            outputTokens: 0,
142	            costUsd: 0,
143	            latencyMs: 0,
144	          };
145	          try {
146	            appendAnalyticsEntry({
147	              id: randomUUID(),
148	              endpoint,
149	              ...usage,
150	              timestamp: new Date().toISOString(),
151	            });
152	          } catch { /* non-fatal */ }
153	          controller.enqueue(sseEvent("done", { text: "", usage }));
154	          controller.close();
155	        }
156	      } catch (err) {
157	        const message = err instanceof Error ? err.message : "Unknown error";
158	        // Provider error bodies can echo parts of the request, so don't write
159	        // them to logs or send them to the client over SSE.
160	        console.error(`[${endpoint}] Stream error: ${message}`);
161	        try {
162	          controller.enqueue(sseEvent("error", { error: message }));
163	        } catch { /* controller may already be closed */ }
164	        try { controller.close(); } catch { /* already closed */ }
165	      }
166	    },
167	  });
168	}
169	
170	/**
171	 * Simulate token-by-token streaming from a cached result.
172	 * Emits chunks of ~20 chars with a small delay between each,
173	 * so the client sees the same partial-JSON rendering behavior
174	 * as a real LLM stream.
175	 */
176	async function simulateStreamFromCache(
177	  controller: ReadableStreamDefaultController<Uint8Array>,
178	  text: string,
179	  usage: LlmCallUsage,
180	): Promise<void> {
181	  const CHUNK_SIZE = 20;
182	  const DELAY_MS = 15;
183	
184	  for (let i = 0; i < text.length; i += CHUNK_SIZE) {
185	    const chunk = text.slice(i, i + CHUNK_SIZE);
186	    controller.enqueue(sseEvent("token", { text: chunk }));
187	    await new Promise((resolve) => setTimeout(resolve, DELAY_MS));
188	  }
189	
190	  controller.enqueue(sseEvent("done", { text, usage }));
191	}
192	
193	type StreamProviderOptions = {
194	  apiKey: string;
195	  model: string;
196	  systemPrompt: string;
197	  userContent: string;
198	  maxTokens: number;
199	  endpoint: string;
200	  cacheHash: string;
201	};
202	
203	async function streamAnthropic(
204	  controller: ReadableStreamDefaultController<Uint8Array>,
205	  opts: StreamProviderOptions,
206	): Promise<void> {
207	  const client = makeAnthropicClient(opts.apiKey);
208	  const start = Date.now();
209	
210	  const stream = client.messages.stream({
211	    model: opts.model,
212	    max_tokens: opts.maxTokens,
213	    system: opts.systemPrompt,
214	    messages: [{ role: "user", content: opts.userContent }],
215	  });
216	
217	  let accumulated = "";
218	
219	  stream.on("text", (text) => {
220	    accumulated += text;
221	    controller.enqueue(sseEvent("token", { text }));
222	  });
223	
224	  const finalMessage = await stream.finalMessage();
225	  const latencyMs = Date.now() - start;
226	
227	  const usage: LlmCallUsage = {
228	    provider: "anthropic",
229	    model: opts.model,
230	    inputTokens: finalMessage.usage.input_tokens,
231	    outputTokens: finalMessage.usage.output_tokens,
232	    costUsd: computeCost(opts.model, finalMessage.usage.input_tokens, finalMessage.usage.output_tokens),
233	    latencyMs,
234	  };
235	
236	  await recordAndCache(opts.endpoint, usage, accumulated, opts.cacheHash);
237	  controller.enqueue(sseEvent("done", { text: accumulated, usage }));
238	  controller.close();
239	}
